def _raise_type_error_on_unknown_kwargs(cls):
    """Reject unexpected `__init__` keyword arguments with a `TypeError`.

    Pydantic 2 reports them as a `ValidationError` instead, whereas a plain
    Python call (and Pydantic 1) raises `TypeError`.
    """
    pydantic_init = cls.__init__

    @wraps(pydantic_init)
    def __init__(self, *args, **kwargs):
        known = {f.name for f in fields(cls) if f.init}
        unexpected = sorted(set(kwargs) - known)
        if unexpected:
            raise TypeError(
                f"{cls.__name__}.__init__() got unexpected keyword argument(s): "
                + ", ".join(unexpected)
            )
        pydantic_init(self, *args, **kwargs)

    cls.__init__ = __init__
    return cls


